use tjspace_core::patch_db::*;use serde_json::json;
#[test]fn snapshot_and_revision(){let d=PatchDb::open_database(":memory:").unwrap();assert_eq!(d.get_revision().unwrap(),0);let x=d.apply_patch(Patch{version:1,path:"system.name".into(),op:PatchOp::Set,value:Some(json!("TJ")),actor:"test".into(),authorization:"allow".into()}).unwrap();assert_eq!(x.revision,1);assert_eq!(d.get_snapshot().unwrap().state["system"]["name"],"TJ");}
#[test]fn delete_and_reconcile(){let d=PatchDb::open_database(":memory:").unwrap();d.apply_patch(Patch{version:1,path:"a".into(),op:PatchOp::Set,value:Some(json!(1)),actor:"t".into(),authorization:"allow".into()}).unwrap();let x=d.apply_patch(Patch{version:1,path:"a".into(),op:PatchOp::Delete,value:None,actor:"t".into(),authorization:"allow".into()}).unwrap();assert_eq!(d.reconcile(0).unwrap().len(),2);assert_eq!(x.previous,Some(json!(1)));}
#[test]fn validation(){let d=PatchDb::open_database(":memory:").unwrap();assert!(d.validate_patch(&Patch{version:99,path:"a".into(),op:PatchOp::Set,value:Some(json!(1)),actor:"t".into(),authorization:"deny".into()}).is_err());}
#[test]fn monotonic(){let d=PatchDb::open_database(":memory:").unwrap();for i in 0..5{d.apply_patch(Patch{version:1,path:format!("a{i}"),op:PatchOp::Set,value:Some(json!(i)),actor:"t".into(),authorization:"allow".into()}).unwrap();}assert_eq!(d.get_revision().unwrap(),5);}
#[test]fn diff_stream(){let d=PatchDb::open_database(":memory:").unwrap();let mut rx=d.subscribe_to_diffs(DiffFilter::default());d.apply_patch(Patch{version:1,path:"x".into(),op:PatchOp::Set,value:Some(json!(true)),actor:"t".into(),authorization:"allow".into()}).unwrap();assert_eq!(rx.try_recv().unwrap().revision,1);}
